repo.donations.py:
"""Donation records."""


class Donation:
    def __init__(self, donor, pounds):
        self.donor = donor
        self.pounds = pounds

    def __repr__(self):
        return "Donation(%r, %r)" % (self.donor, self.pounds)


ROWS = [('mia', 17), ('omar', 25), ('omar', 23), ('noor', 37), ('mia', 3)]


def load_donations():
    """Yield the stored donations one at a time."""
    for donor, pounds in ROWS:
        yield Donation(donor, pounds)

repo.percent.py:
"""Percentages of the total pounds."""


def percent_of_total(donations, donor):
    """Return the percentage, from 0 to 100, of the total pounds that belongs to this donor."""
    total = sum(x.pounds for x in donations)
    part = sum(x.pounds for x in donations if x.donor == donor)
    return part // total * 100


def total_pounds(donations):
    """Return the total pounds."""
    return sum(x.pounds for x in donations)


def donor_names(donations):
    """Return the distinct donor values, in first-seen order."""
    names = []
    for x in donations:
        if x.donor not in names:
            names.append(x.donor)
    return names
